#[derive(Clone,Debug,PartialEq,Eq)]pub struct RegisterN<const LIMBS:usize>{pub limbs:[u64;LIMBS]}
impl<const L:usize> RegisterN<L>{pub fn zero()->Self{Self{limbs:[0;L]}} pub fn from_hex(s:&str)->Result<Self,&'static str>{let t=s.trim_start_matches("0x");if t.len()>L*16{return Err("value exceeds register width")}let mut r=Self::zero();for(i,ch)in t.as_bytes().rchunks(16).enumerate(){let x=std::str::from_utf8(ch).map_err(|_|"utf8")?;r.limbs[i]=u64::from_str_radix(x,16).map_err(|_|"hex")?;}Ok(r)} pub fn to_hex(&self)->String{let mut s=String::new();for &x in self.limbs.iter().rev(){s.push_str(&format!("{:016x}",x));}let z=s.trim_start_matches('0');if z.is_empty(){"0".into()}else{z.into()}}}
#[cfg(test)]mod tests{use super::*;#[test]fn hex_roundtrip(){let r=RegisterN::<2>::from_hex("1234abcd").unwrap();assert_eq!(r.to_hex(),"1234abcd");}}
